<?php require_once __DIR__.'/config.php';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pdo=get_db_connection();$ref=trim($_GET['ref']??'');if(!$pdo||$ref===''){http_response_code(404);exit('Ticket not found');}xinng_ensure_page_builder_tables($pdo);$q=$pdo->prepare('SELECT o.*,p.title,p.slug,t.name ticket_name,pe.start_at,pe.venue,pe.city FROM event_orders o JOIN pages p ON p.id=o.page_id JOIN event_ticket_types t ON t.id=o.ticket_type_id LEFT JOIN page_events pe ON pe.page_id=p.id WHERE o.order_ref=?');$q->execute([$ref]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Ticket not found');}$valid=in_array($o['payment_status'],['free','paid'],true);$qr='https://api.qrserver.com/v1/create-qr-code/?size=220x220&data='.rawurlencode(xinng_public_base_url().'/event_orders.php?checkin='.$o['ticket_code']);?><!doctype html><meta name="viewport" content="width=device-width"><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#fff9f7;font-family:Arial;color:#201a19}.t{width:min(440px,calc(100% - 28px));overflow:hidden;border:1px solid #e7dedb;border-radius:20px;background:#fff;box-shadow:0 25px 60px #201a1918}.h{padding:28px;background:#201a19;color:#fff}.b{padding:26px}.r{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #eee}.qr{text-align:center;padding:22px}.qr img{width:200px}.ok{padding:12px;border-radius:9px;background:#e8f7ec;color:#18723a;font-weight:bold}a{display:block;margin-top:18px;color:#e83b32;text-align:center}</style><main class="t"><div class="h"><small><?=e($o['order_ref'])?></small><h1><?=e($o['title'])?></h1></div><div class="b"><div class="ok"><?=$valid?'Registration confirmed':'Payment pending'?></div><div class="r"><span>Attendee</span><strong><?=e($o['attendee_name'])?></strong></div><div class="r"><span>Ticket</span><strong><?=e($o['ticket_name'])?> × <?=(int)$o['quantity']?></strong></div><div class="r"><span>Date</span><strong><?=e(date('M j, Y · g:i A',strtotime($o['start_at'])))?></strong></div><div class="r"><span>Location</span><strong><?=e(trim(($o['venue']??'').', '.($o['city']??''),', '))?></strong></div><?php if($valid):?><div class="qr"><img src="<?=e($qr)?>"><div><?=e($o['ticket_code'])?></div></div><?php endif;?><a href="<?=e(xinng_short_url($o['slug']))?>">Back to event</a></div></main>
